const icon=(name)=>`<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${icons[name]??icons.more}"/></svg>`;
const navItems=[['home','Ma','home'],['tasks','Feladatok','tasks'],['calendar','Naptár','calendar'],['study','Tanulás','study'],['journal','Napló','journal'],['habits','Szokások','habits'],['analytics','Áttekintés','analytics'],['settings','Beállítások','settings']];
const button=(label,action,cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const navButton=(name,label,ico)=>`<button data-nav="${name}" class="${route===name?'active':''}" ${route===name?'aria-current="page"':''}>${icon(ico)}${label}</button>`;
const title=(name,sub,action='')=>`<div class="page-title"><div><div class="eyebrow">SZEMÉLYES IRÁNYÍTÓKÖZPONT</div><h1>${name}</h1><p>${sub}</p></div>${action}</div>`;
const empty=(name,sub,action='')=>`<div class="empty"><strong>${name}</strong><p>${sub}</p>${action}</div>`;
const badge=(name,cls='')=>`<span class="pill ${cls}">${esc(name)}</span>`;
const card=(heading,body,action='')=>`<section class="card"><div class="card-header"><h2>${heading}</h2>${action}</div>${body}</section>`;
const dateLabel=d=>new Intl.DateTimeFormat('hu-HU',{month:'long',day:'numeric',weekday:'long'}).format(new Date(d+'T12:00:00Z'));
